<span class="line"><span style="color:#E06C75;">        autoscaling.knative.dev/minScale</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">&quot;1&quot;</span><span style="color:#7F848E;font-style:italic;">     # 至少保留 1 个 Pod</span></span>
