<span class="line"><span style="color:#E06C75;">        autoscaling.knative.dev/scaleDownDelay</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">&quot;300s&quot;</span><span style="color:#7F848E;font-style:italic;">  # 缩容延迟 5 分钟</span></span>
