<span class="line"><span style="color:#61AFEF;">FROM</span><span style="color:#ABB2BF;"> mcr.microsoft.com/dotnet/sdk:8.0-alpine </span><span style="color:#61AFEF;">AS</span><span style="color:#ABB2BF;"> build</span></span>
